CREATE TYPE "Role" AS ENUM ('CUSTOMER', 'OWNER', 'MANAGER', 'SUPPORT');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL, "name" TEXT NOT NULL, "passwordHash" TEXT NOT NULL, "role" "Role" NOT NULL DEFAULT 'CUSTOMER', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "CommerceState" ("id" TEXT PRIMARY KEY DEFAULT 'main', "version" INTEGER NOT NULL DEFAULT 0, "data" JSONB NOT NULL, "updatedAt" TIMESTAMP(3) NOT NULL);
